// Parse and prepare enrollments for processing
const enrollments = $input.all();
const results = [];

for (const item of enrollments) {
  const data = item.json;
  if (!Array.isArray(data)) continue;

  for (const enrollment of data) {
    const lead = enrollment.leads;
    if (!lead) continue;

    // Determine message based on current_step
    const step = enrollment.current_step || 0;
    const daysSinceEnroll = Math.floor((Date.now() - new Date(enrollment.enrolled_at).getTime()) / (1000 * 60 * 60 * 24));

    // Only send if it's been enough days since last step
    const stepDelays = [0, 3, 7, 14]; // days between steps
    const expectedDay = stepDelays.slice(0, step + 1).reduce((a, b) => a + b, 0);

    if (daysSinceEnroll < expectedDay) continue;

    const isSpanish = lead.tags?.includes('Spanish') || lead.tags?.includes('ES');

    // Build message for each step
    const messages = {
      en: [
        `Hi ${lead.first_name}! This is Lorena Ontiveros-Ortega, your El Paso real estate expert. I noticed we haven't connected in a while. El Paso's market has some exciting opportunities right now — homes in your area are moving fast! When would be a good time to chat? Call or text me at (915) 500-0573. 🏡`,
        `${lead.first_name}, Lorena here! Just wanted to share — El Paso home values have shifted recently and I'd love to give you a personalized update. Whether you're buying, selling, or just curious, I'm here to help. No pressure! Text back anytime or visit CasasEnElPaso.com`,
        `Hey ${lead.first_name}! Quick update from Lorena — I just pulled the latest market stats for El Paso and there are some incredible deals right now. Buyers are competing and sellers are winning big. Can I send you a quick market report? Just reply YES! 📊`,
        `${lead.first_name}, this is Lorena one last time. I don't want to keep reaching out if the timing isn't right, but I do want to make sure you know I'm here whenever you're ready. El Paso real estate is my passion and helping people like you is why I do this. Call me anytime: (915) 500-0573. Take care! 💛`
      ],
      es: [
        `¡Hola ${lead.first_name}! Soy Lorena Ontiveros-Ortega, tu experta en bienes raíces en El Paso. Noté que no hemos hablado en un tiempo. ¡El mercado de El Paso tiene oportunidades increíbles ahora mismo! ¿Cuándo podemos hablar? Llámame o mándame un mensaje al (915) 500-0573. 🏡`,
        `${lead.first_name}, ¡es Lorena! Quería compartir — los valores de las casas en El Paso han cambiado recientemente y me encantaría darte una actualización personalizada. Ya sea que quieras comprar, vender, o solo informarte, estoy aquí para ayudarte. Sin presión. Escríbeme cuando quieras o visita CasasEnElPaso.com`,
        `¡Hola ${lead.first_name}! Lorena aquí con una actualización rápida — acabo de revisar las estadísticas más recientes del mercado de El Paso y hay ofertas increíbles ahora. Los compradores están compitiendo y los vendedores están ganando. ¿Te mando un reporte del mercado? ¡Solo responde SÍ! 📊`,
        `${lead.first_name}, esta es Lorena por última vez. No quiero seguir escribiendo si el momento no es el adecuado, pero quiero que sepas que estoy aquí cuando estés listo/a. Los bienes raíces en El Paso son mi pasión. Llámame cuando quieras: (915) 500-0573. ¡Cuídate mucho! 💛`
      ]
    };

    const msgList = isSpanish ? messages.es : messages.en;
    const message = msgList[Math.min(step, msgList.length - 1)];

    results.push({
      enrollment_id: enrollment.id,
      lead_id: enrollment.lead_id,
      current_step: step,
      next_step: step + 1,
      phone: lead.phone,
      email: lead.email,
      first_name: lead.first_name,
      last_name: lead.last_name,
      message,
      should_complete: step >= 3,
      has_phone: !!lead.phone,
      has_email: !!lead.email
    });
  }
}

return results.map(r => ({ json: r }));
